    "Design a custom parliament with configurable seats, parties, factions, coalitions, independents and over 100 ideologies. Simulate legislative votes with party discipline, voting behaviour and custom majority rules—all in your browser, completely free.": "Design a custom parliament with configurable seats, parties, factions, coalitions, independents and over 100 ideologies. Simulate legislative votes with party discipline, voting behaviour and custom majority rules—all in your browser, completely free.",
    "Build a fictional legislature or model a real parliamentary structure. Arrange the chamber, define its political forces and test how legislation moves through a voting system shaped by your own assumptions.": "Build a fictional legislature or model a real parliamentary structure. Arrange the chamber, define its political forces and test how legislation moves through a voting system shaped by your own assumptions.",
