    "Explore more than 100 political ideologies": "Explore more than 100 political ideologies",
    "Use a built-in library of 130 researched ideology entries covering the far left, left, centre-left, centre, centre-right, right, far right and third-way traditions. Search entries, review descriptions and historical context, or create custom ideologies for your own political setting.": "Use a built-in library of 130 researched ideology entries covering the far left, left, centre-left, centre, centre-right, right, far right and third-way traditions. Search entries, review descriptions and historical context, or create custom ideologies for your own political setting.",
    "Simulate parliamentary votes": "Simulate parliamentary votes",
    "Configure a bill, resolution, motion, amendment or confidence vote. Deputies can vote according to party instructions, faction positions, ideology, individual decisions, random probabilities or mixed rules.": "Configure a bill, resolution, motion, amendment or confidence vote. Deputies can vote according to party instructions, faction positions, ideology, individual decisions, random probabilities or mixed rules.",
    "Model political discipline and constitutional rules": "Model political discipline and constitutional rules",
