    "Review results and export your work": "Review results and export your work",
    "Inspect vote totals and deputy-level outcomes, keep a history of votes, compare two recorded votes, and export parliament compositions or voting records in CSV and JSON formats.": "Inspect vote totals and deputy-level outcomes, keep a history of votes, compare two recorded votes, and export parliament compositions or voting records in CSV and JSON formats.",
    "A parliamentary voting simulator with faction-level detail": "A parliamentary voting simulator with faction-level detail",
    "A parliamentary voting simulator is only as useful as the political assumptions behind its results. Here, voting behaviour can be configured at several levels: a party can issue a voting line, factions within that party can take different positions, ideologies can guide deputies, and individual MPs can receive their own decisions. Mixed mode lets different groups follow different decision methods in the same vote.": "A parliamentary voting simulator is only as useful as the political assumptions behind its results. Here, voting behaviour can be configured at several levels: a party can issue a voting line, factions within that party can take different positions, ideologies can guide deputies, and individual MPs can receive their own decisions. Mixed mode lets different groups follow different decision methods in the same vote.",
    "The result is a configurable scenario model, not a prediction of how a real parliament will vote. It calculates outcomes from the parties, factions, deputies, voting behaviour and passage rules that you define.": "The result is a configurable scenario model, not a prediction of how a real parliament will vote. It calculates outcomes from the parties, factions, deputies, voting behaviour and passage rules that you define.",
    "Who is it for?": "Who is it for?",
    "Use the parliament builder for alternate history, fictional elections, political worldbuilding, classroom exercises, constitutional experiments, role-playing settings or exploring how changes in party discipline and coalition structure affect a parliamentary majority.": "Use the parliament builder for alternate history, fictional elections, political worldbuilding, classroom exercises, constitutional experiments, role-playing settings or exploring how changes in party discipline and coalition structure affect a parliamentary majority.",
