    "A coalition is a cooperation between parties — it does": "Коалиция — это сотрудничество между партиями; она не",
    "not": "не",
    "merge them. Member parties keep their colours and are marked with the coalition-coloured ring. Parties may belong to several coalitions; the first coalition in the list determines the ring colour.": "объединение. Партии-участницы сохраняют свои цвета и отмечаются кольцом цвета коалиции. Партия может входить в несколько коалиций; цвет кольца определяется первой коалицией в списке.",
    "Create parties first.": "Сначала создайте партии.",
    "Designate as government": "Назначить правительством",
    "Highlight in chamber": "Выделить в зале заседаний",
    "Factions are internal groups of a single party. A faction can hold its own ideology, independent of the party's. Assign deputies with a seat count or pick them one by one.": "Фракции — это внутренние группы одной партии. Фракция может иметь собственную идеологию, отличную от идеологии партии. Назначайте депутатов по количеству мест или выбирайте их по одному.",
