    "No parties to configure.": "Нет партий для настройки.",
    "Specific ideology overrides": "Индивидуальные переопределения идеологии",
    "No deputies match.": "Нет подходящих депутатов.",
    "Weights are normalised automatically so they always sum to 100%. Absent deputies do not count as present.": "Веса автоматически нормализуются до 100%. Отсутствующие депутаты не считаются присутствующими.",
    "All weights are zero — they will be treated as equal.": "Все веса равны нулю — они будут считаться равными.",
