    "The researched database was compiled from Wikipedia (spectrum and category articles), Britannica, and OpenStax/LibreTexts, then checked for distinctness: synonyms are listed as alternative names rather than separate entries. Classifications are approximations, not universal definitions.": "Die recherchierte Datenbank basiert auf Wikipedia-Artikeln zum politischen Spektrum und seinen Kategorien, Britannica sowie OpenStax/LibreTexts. Anschließend wurden die Einträge auf Eigenständigkeit geprüft: Synonyme erscheinen als alternative Namen und nicht als separate Einträge. Die Einordnungen sind Näherungen, keine universellen Definitionen.",
