    "Toggle the vote result overlay": "Abstimmungsergebnis-Einblendung umschalten",
    "Manual seating is locked. Use Auto-arrange in the Parliament tab to restore party blocks.": "Die manuelle Sitzordnung ist gesperrt. Verwenden Sie „Automatisch anordnen“ im Reiter „Parlament“, um die Parteiblöcke wiederherzustellen.",
    "Coalition": "Koalition",
    "Factions, parties and coalitions": "Fraktionen, Parteien und Koalitionen",
