    "A coalition is a cooperation between parties — it does": "Eine Koalition ist eine Zusammenarbeit zwischen Parteien – sie",
    "not": "nicht",
    "merge them. Member parties keep their colours and are marked with the coalition-coloured ring. Parties may belong to several coalitions; the first coalition in the list determines the ring colour.": "werden nicht zusammengelegt. Mitgliedsparteien behalten ihre Farben und werden durch einen Ring in Koalitionsfarbe markiert. Parteien können mehreren Koalitionen angehören; die erste Koalition in der Liste bestimmt die Ringfarbe.",
    "Create parties first.": "Erstellen Sie zuerst Parteien.",
    "Designate as government": "Als Regierung festlegen",
    "Highlight in chamber": "Im Plenum hervorheben",
    "Factions are internal groups of a single party. A faction can hold its own ideology, independent of the party's. Assign deputies with a seat count or pick them one by one.": "Fraktionen sind interne Gruppen einer einzelnen Partei. Eine Fraktion kann unabhängig von der Partei eine eigene Ideologie vertreten. Weisen Sie Abgeordnete anhand einer Sitzanzahl zu oder wählen Sie sie einzeln aus.",
