    "Weights are normalised automatically so they always sum to 100%. Absent deputies do not count as present.": "Die Gewichtungen werden automatisch auf 100 % normiert. Abwesende Abgeordnete zählen nicht als anwesend.",
    "All weights are zero — they will be treated as equal.": "Alle Gewichtungen sind null – sie werden als gleich behandelt.",
