    "HEX colour": "HEX-Farbe",
    "The original ideology descriptions and historical metadata are preserved. Positions are broad reference classifications; political movements have varied across time and place.": "Die ursprünglichen Ideologiebeschreibungen und historischen Angaben bleiben erhalten. Die Positionen sind grobe Orientierungsklassifikationen; politische Bewegungen unterschieden sich je nach Zeit und Ort.",
