    "Delete {name}? It is used by {count} party/faction/deputy entries, which will become unassigned.": "„{name}“ löschen? Die Ideologie wird in {count} Partei-, Fraktions- oder Abgeordneteneinträgen verwendet; diese Einträge verlieren danach ihre Zuordnung.",
    "Government offices": "Regierungsämter",
    "Appoint sitting deputies from Government-designated parties, or enter an external officeholder by name.": "Ernennen Sie amtierende Abgeordnete aus Parteien mit Regierungsstatus oder geben Sie den Namen einer externen Amtsperson ein.",
    "eligible deputies": "wählbare Abgeordnete",
    "Filled": "Besetzt",
    "Total offices": "Ämter insgesamt",
    "No government offices have been created yet.": "Es wurden noch keine Regierungsämter angelegt.",
    "Position name": "Amtsbezeichnung",
    "Remove this position": "Dieses Amt entfernen",
    "Describe the responsibilities of this office…": "Beschreiben Sie die Aufgaben dieses Amtes…",
    "Deputy appointment": "Ernennung eines Abgeordneten",
    "Only deputies from parties marked Government are selectable. A deputy may hold more than one office.": "Es können nur Abgeordnete aus Parteien mit dem Status Regierung ausgewählt werden. Ein Abgeordneter kann mehrere Ämter innehaben.",
    "No deputy selected": "Kein Abgeordneter ausgewählt",
    "This deputy is no longer eligible because their party is not currently designated Government. Clear or replace the appointment.": "Dieser Abgeordnete ist nicht mehr wählbar, da seine Partei nicht mehr als Regierungspartei eingestuft ist. Heben Sie die Ernennung auf oder ersetzen Sie sie.",
    "External / non-deputy appointee": "Externe Besetzung / keine Abgeordneten",
    "Use this for presidents, monarch-appointed ministers, technocrats or other officeholders who are not sitting government deputies.": "Verwenden Sie dies für Präsidenten, vom Monarchen ernannte Minister, Fachleute oder andere Amtsträger, die keine amtierenden Abgeordneten einer Regierungspartei sind.",
    "Enter a person's name": "Namen der Person eingeben",
    "Custom position": "Benutzerdefiniertes Amt",
    "Create custom position": "Benutzerdefiniertes Amt erstellen",
    "Describe the office's purpose and responsibilities…": "Beschreiben Sie Zweck und Aufgaben des Amtes…",
    "Add position": "Amt hinzufügen",
    "+ Add custom position": "+ Benutzerdefiniertes Amt hinzufügen",
    "Appointment statistics": "Ernennungsstatistik",
    "Party and ideological-family totals count deputies currently appointed from Government-designated parties. External appointees are counted separately.": "Die Partei- und Ideologiefamilienstatistik zählt Abgeordnete, die derzeit aus Regierungsparteien ernannt wurden. Externe Amtsträger werden separat gezählt.",
    "Appointments by party": "Ernennungen nach Partei",
    "Appointments by ideological family": "Ernennungen nach ideologischer Familie",
    "No deputy appointments yet.": "Noch keine Abgeordneten ernannt.",
    "Elections…": "Wahlen…",
    "Election options": "Wahloptionen",
    "Configure the scale of seat changes and any optional ideological preference.": "Legen Sie das Ausmaß der Sitzverschiebungen und eine optionale ideologische Präferenz fest.",
    "Election volatility": "Wahlbewegung",
    "Choose how strongly election results may shift party seat allocations.": "Bestimmen Sie, wie stark das Wahlergebnis die Sitzverteilung der Parteien verändern kann.",
    "1 — Gentle": "1 — Gering",
    "10 — Dramatic": "10 — Radikal",
    "Electoral momentum": "Wahlrückenwind",
    "Optional preference for parties belonging to one ideological family.": "Optionale Bevorzugung von Parteien einer ideologischen Familie.",
    "Momentum strength": "Stärke des Rückenwinds",
    "Higher settings give the selected family a stronger advantage in the election.": "Höhere Werte verschaffen der ausgewählten Familie einen größeren Vorteil bei der Wahl.",
    "1 — Subtle": "1 — Leicht",
    "10 — Landslide": "10 — Erdrutschsieg",
    "Hold election": "Wahl durchführen",
    "Election complete. Parliament's seat allocation has been updated.": "Die Wahl ist abgeschlossen. Die Sitzverteilung im Parlament wurde aktualisiert.",
    "Allocate at least one seat to a party before holding an election.": "Weisen Sie vor der Wahl mindestens einer Partei einen Sitz zu.",
