    "merge them. Member parties keep their colours and are marked with the coalition-coloured ring. Parties may belong to several coalitions; the first coalition in the list determines the ring colour.": "ne les fusionne pas. Les partis membres conservent leurs couleurs et sont entourés d’un anneau de la couleur de la coalition. Un parti peut appartenir à plusieurs coalitions ; la première de la liste détermine la couleur de l’anneau.",
