    "Gradual collectivism": "Collectivisme graduel",
    "Reformist": "Réformiste",
    "Macroeconomic school supporting active government demand management to stabilise the economy.": "École macroéconomique qui soutient une gestion active de la demande par l’État afin de stabiliser l’économie.",
    "Counter-cyclical state spending": "Dépenses publiques contracycliques",
