    "Promotes the recognition and accommodation of diverse cultural and ethnic groups in one society.": "Favorise la reconnaissance et la prise en compte de groupes culturels et ethniques divers au sein d’une même société.",
    "Pluralist, minority rights": "Pluraliste, droits des minorités",
