    "Liberal-democratic": "Libéral-démocratique",
    "Applies Christian ethics to justice, poverty and peace, leaning toward egalitarian and welfare policy.": "Applique l’éthique chrétienne aux questions de justice, de pauvreté et de paix, en privilégiant des politiques égalitaires et sociales.",
    "Welfare, social justice": "Protection sociale, justice sociale",
    "Faith-based progressive": "Progressiste fondé sur la foi",
