    "Historically close to social democracy; modern usage often means radical-left within democracy, so placement between centre-left and left is approximate.": "Historiquement proche de la social-démocratie ; dans l’usage actuel, le terme désigne souvent une gauche radicale démocratique. Son placement entre le centre gauche et la gauche reste donc approximatif.",
