    "Poor-centred, communitarian": "Centré sur les pauvres, communautaire",
    "Nationalism of liberation and self-determination combined with social equality aims.": "Nationalisme de libération et d’autodétermination associé à des objectifs d’égalité sociale.",
    "Social development, nationalisation": "Développement social, nationalisation",
