    "Collective development": "Développement collectif",
    "Anti-colonial, solidarity": "Anticolonial, solidaire",
    "Argues for planned reduction of production and consumption to stay within ecological limits while improving wellbeing.": "Préconise une réduction planifiée de la production et de la consommation afin de respecter les limites écologiques tout en améliorant le bien-être.",
    "Post-growth, sufficiency": "Post-croissance, sobriété",
    "Sometimes classified as a third-way/ecologist position outside left–right.": "Parfois classé comme une position écologiste de troisième voie, en dehors de l’axe gauche-droite.",
    "Aim of a classless, moneyless, stateless society based on common ownership of the means of production.": "Vise une société sans classes, sans argent et sans État, fondée sur la propriété commune des moyens de production.",
