    "Class-based egalitarian": "Égalitaire fondé sur les classes",
    "Lenin's theory of a disciplined vanguard party leading proletarian revolution and a transitional state.": "Théorie de Lénine d’un parti d’avant-garde discipliné dirigeant la révolution prolétarienne et un État de transition.",
