    "Command economy": "Économie dirigée",
    "One-party, authoritarian": "Parti unique, autoritaire",
    "Marxism–Leninism as practised under Stalin: socialism in one country, forced industrialisation and personalised party rule.": "Marxisme-léninisme sous Staline : socialisme dans un seul pays, industrialisation forcée et pouvoir partisan personnalisé.",
    "Central planning, collectivisation": "Planification centrale, collectivisation",
    "Totalitarian": "Totalitaire",
