    "Collectivised rural-led economy": "Économie collectivisée portée par le monde rural",
    "Mass-line, authoritarian": "Ligne de masse, autoritaire",
    "Enver Hoxha's strictly Stalinist, anti-revisionist line rejecting Soviet reform and Maoism.": "Ligne strictement stalinienne et antirévisionniste d’Enver Hoxha, rejetant les réformes soviétiques et le maoïsme.",
    "Strict central planning, autarky": "Planification centrale stricte, autarcie",
