    "Revolutionary Marxism stressing mass spontaneity, democracy within socialism and opposition to bureaucratic vanguardism.": "Marxisme révolutionnaire mettant l’accent sur la spontanéité des masses, la démocratie au sein du socialisme et l’opposition à l’avant-gardisme bureaucratique.",
    "Socialised production": "Production socialisée",
