    "The original ideology descriptions and historical metadata are preserved. Positions are broad reference classifications; political movements have varied across time and place.": "Les descriptions originales des idéologies et les informations historiques sont conservées. Les positions constituent des classifications générales indicatives ; les mouvements politiques ont varié selon les époques et les lieux.",
