    "Only deputies from parties marked Government are selectable. A deputy may hold more than one office.": "Seuls les députés des partis désignés comme membres du gouvernement peuvent être sélectionnés. Un député peut occuper plusieurs postes.",
    "No deputy selected": "Aucun député sélectionné",
    "This deputy is no longer eligible because their party is not currently designated Government. Clear or replace the appointment.": "Ce député n’est plus éligible, car son parti n’est plus désigné comme membre du gouvernement. Annulez ou remplacez cette nomination.",
    "External / non-deputy appointee": "Personne extérieure / non-député",
    "Use this for presidents, monarch-appointed ministers, technocrats or other officeholders who are not sitting government deputies.": "Utilisez ce champ pour les présidents, les ministres nommés par un monarque, les technocrates ou d’autres titulaires qui ne siègent pas comme députés d’un parti gouvernemental.",
