    "Appointment statistics": "Statistiques des nominations",
    "Party and ideological-family totals count deputies currently appointed from Government-designated parties. External appointees are counted separately.": "Les totaux par parti et famille idéologique comptent les députés nommés depuis des partis désignés comme membres du gouvernement. Les personnes extérieures sont comptées séparément.",
    "Appointments by party": "Nominations par parti",
