    "Optional preference for parties belonging to one ideological family.": "Préférence facultative pour les partis appartenant à une famille idéologique.",
    "Momentum strength": "Intensité de la dynamique",
    "Higher settings give the selected family a stronger advantage in the election.": "Une valeur élevée renforce l’avantage électoral de la famille sélectionnée.",
    "1 — Subtle": "1 — Léger",
