    "Co-op ownership": "合作社所有制",
    "Solidarity, participation": "团结、参与",
    "Proudhon's system of reciprocal exchange, mutual credit and worker-controlled production.": "蒲鲁东提出的互惠交换、互助信贷和工人控制生产的体系。",
    "Mutual credit, possession": "互助信贷、占有",
    "Federalist, anti-state": "联邦主义、反国家主义",
    "British movement for workers' control through democratic industrial guilds within a pluralist state.": "英国的一场运动，主张在多元主义国家框架内通过民主工业行会实现工人控制。",
    "Guild-run industry": "行会管理的工业",
    "Mobilises 'the people' against economic and political elites, combining redistribution with anti-establishment rhetoric.": "动员“人民”反对经济和政治精英，将再分配与反建制言论相结合。",
    "Redistribution, anti-austerity": "再分配、反紧缩",
    "Inclusive-popular": "包容性、人民导向",
    "Western European communist current that accepted pluralist democracy and rejected Soviet control.": "西欧共产主义思潮，接受多元主义民主并反对苏联控制。",
    "Mixed, social ownership": "混合型、社会所有制",
    "Democratic, pluralist": "民主主义、多元主义",
    "Latin American movement inspired by Simón Bolívar, combining socialism, anti-imperialism and popular participation.": "受西蒙·玻利瓦尔启发的拉丁美洲运动，结合社会主义、反帝国主义和民众参与。",
    "Nationalised resources, social missions": "资源国有化、社会使命计划",
    "Populist, anti-imperialist": "民粹主义、反帝国主义",
    "Murray Bookchin's view that ecological crises stem from hierarchy; proposes confederated democratic municipalities.": "默里·布克钦认为生态危机源于等级制度，并提出建立民主市镇联合体。",
    "Communal / municipal economy": "共同体／市镇经济",
    "Directly democratic": "直接民主主义",
