    "Economic doctrine from Catholic social teaching (Chesterton, Belloc) favouring widespread ownership of productive property, neither capitalism nor socialism.": "Doktrin ekonomi dari ajaran sosial Katolik (Chesterton, Belloc) yang mendukung kepemilikan luas atas properti produktif, bukan kapitalisme maupun sosialisme.",
