    "Statist developmentalism": "Developmentalisme statis",
    "Secular, modernising, nationalist": "Sekuler, modernis, nasionalis",
    "Thin-centred ideology dividing society into 'the pure people' versus 'the corrupt elite' (Mudde); attaches to left, right or centre.": "Ideologi tipis yang membagi masyarakat menjadi “rakyat yang murni” dan “elite yang korup” (Mudde); dapat melekat pada posisi kiri, kanan, atau tengah.",
    "Anti-establishment": "Anti-kemapanan",
    "Scholars treat populism as a thin ideology that attaches to others, not a left–right position.": "Para sarjana memandang populisme sebagai ideologi tipis yang melekat pada ideologi lain, bukan posisi kiri–kanan tersendiri.",
    "Positions that deliberately mix elements from across the left–right spectrum.": "Posisi yang sengaja mencampurkan unsur-unsur dari seluruh spektrum kiri–kanan.",
    "Mixed": "Campuran",
    "Deepens democracy through participation, deliberation and citizens' assemblies beyond electoral representation.": "Memperdalam demokrasi melalui partisipasi, deliberasi, dan majelis warga di luar representasi elektoral.",
    "Participatory": "Partisipatif",
    "Participatory, pluralist": "Partisipatif, pluralis",
    "Political traditions centred on individual rights, liberal institutions, market freedom or voluntary association.": "Tradisi politik yang berpusat pada hak individu, lembaga liberal, kebebasan pasar, atau asosiasi sukarela.",
    "Traditions emphasising continuity, established institutions, social order, inherited practices or conservative reform.": "Tradisi yang menekankan kesinambungan, lembaga mapan, ketertiban sosial, praktik warisan, atau reformasi konservatif.",
    "Reformist traditions pursuing social protection, democratic change, labour rights and mixed-economy institutions.": "Tradisi reformis yang mengupayakan perlindungan sosial, perubahan demokratis, hak buruh, dan lembaga ekonomi campuran.",
    "Socialist and communist currents associated with pluralism, democratic participation, cooperative organisation or opposition to one-party state orthodoxy.": "Aliran sosialis dan komunis yang terkait dengan pluralisme, partisipasi demokratis, organisasi koperasi, atau penentangan terhadap ortodoksi negara satu partai.",
    "Centralised communist traditions built around vanguard-party rule, highly concentrated state power or one-party political systems.": "Tradisi komunis terpusat yang dibangun di atas kekuasaan partai pelopor, pemusatan kekuasaan negara yang tinggi, atau sistem politik satu partai.",
    "Traditions opposing imposed hierarchy and favouring decentralised, voluntary or directly democratic organisation.": "Tradisi yang menentang hierarki yang dipaksakan dan mendukung organisasi yang terdesentralisasi, sukarela, atau demokratis secara langsung.",
    "Traditions centred on national identity, sovereignty, self-determination or geopolitical independence.": "Tradisi yang berpusat pada identitas nasional, kedaulatan, penentuan nasib sendiri, atau kemerdekaan geopolitik.",
    "Fascist and exclusionary ultranationalist doctrines that elevate a totalising national community, hierarchy and authoritarian rule.": "Doktrin fasis dan ultranasionalis eksklusif yang mengagungkan komunitas nasional totalistik, hierarki, dan pemerintahan otoriter.",
    "Traditions grounding political organisation in religious ethics, communal solidarity or shared moral obligations.": "Tradisi yang mendasarkan organisasi politik pada etika agama, solidaritas komunal, atau kewajiban moral bersama.",
    "Civic, ecological, pragmatic and cross-cutting traditions that do not form one conventional ideological family.": "Tradisi kewargaan, ekologis, pragmatis, dan lintas bidang yang tidak membentuk satu keluarga ideologi konvensional.",
    "Emerged as a reaction to the French Revolution (1789); Edmund Burke's Reflections (1790) is its founding text.": "Muncul sebagai reaksi terhadap Revolusi Prancis (1789); Reflections karya Edmund Burke (1790) menjadi teks pendiriannya.",
    "Founded by Mussolini in Italy (1919–1922) in the wake of World War I; spread across interwar Europe.": "Didirikan Mussolini di Italia pada 1919–1922 setelah Perang Dunia I; menyebar ke seluruh Eropa antarperang.",
    "Emerged in Weimar Germany in the 1920s and ruled Germany 1933–1945.": "Muncul di Jerman Weimar pada 1920-an dan memerintah Jerman pada 1933–1945.",
    "Developed from the 17th–19th centuries: Locke, Montesquieu, Adam Smith and J. S. Mill.": "Berkembang dari abad ke-17 hingga ke-19: Locke, Montesquieu, Adam Smith, dan J. S. Mill.",
    "Grew from the late-19th-century split between revolutionary and reformist Marxism; shaped the post-war welfare states.": "Berkembang dari perpecahan antara Marxisme revolusioner dan reformis pada akhir abad ke-19; membentuk negara kesejahteraan pascaperang.",
    "Developed from Catholic social teaching (Rerum Novarum, 1891) and dominated post-war Western Europe.": "Berkembang dari ajaran sosial Katolik (Rerum Novarum, 1891) dan mendominasi Eropa Barat pascaperang.",
    "Formulated by Marx and Engels in the mid-19th century (Communist Manifesto, 1848).": "Dirumuskan oleh Marx dan Engels pada pertengahan abad ke-19 (Manifesto Komunis, 1848).",
    "Developed by Lenin around the 1903 party split and the 1917 Russian Revolution.": "Dikembangkan Lenin sekitar perpecahan partai pada 1903 dan Revolusi Rusia 1917.",
    "Arose in the 1920s as opposition to Stalin's rise; the Fourth International was founded in 1938.": "Muncul pada 1920-an sebagai oposisi terhadap naiknya Stalin; Internasional Keempat didirikan pada 1938.",
    "Developed during the Chinese Revolution (1927–1949).": "Berkembang selama Revolusi Tiongkok (1927–1949).",
    "Formulated in the 1870s–80s by Kropotkin and others; major role in the Spanish Civil War.": "Dirumuskan Kropotkin dan tokoh lain pada 1870-an hingga 1880-an; berperan penting dalam Perang Saudara Spanyol.",
    "Used historically for many projects; after 1990 associated with Giddens, Blair, Clinton and Schröder.": "Secara historis digunakan untuk berbagai proyek; setelah 1990 dikaitkan dengan Giddens, Blair, Clinton, dan Schröder.",
    "Revived in the 1970s–80s through the Chicago and Austrian schools and the Thatcher and Reagan governments.": "Dihidupkan kembali pada 1970-an–1980-an melalui mazhab Chicago dan Austria serta pemerintahan Thatcher dan Reagan.",
    "Modern term for centrism that rejects left–right framing, popularised from the 1990s.": "Istilah modern untuk sentrisme yang menolak kerangka kiri–kanan, populer sejak 1990-an.",
    "Arose from John Maynard Keynes' General Theory (1936) amid the Great Depression.": "Muncul dari General Theory karya John Maynard Keynes (1936) di tengah Depresi Besar.",
    "Developed in the early 20th century by Chesterton and Belloc from Rerum Novarum.": "Dikembangkan pada awal abad ke-20 oleh Chesterton dan Belloc berdasarkan Rerum Novarum.",
    "Founded by Juan Perón in Argentina in the 1940s.": "Didirikan Juan Perón di Argentina pada 1940-an.",
    "Established by Mustafa Kemal Atatürk after 1923 as the Turkish republic's founding ideology.": "Ditetapkan Mustafa Kemal Atatürk setelah 1923 sebagai ideologi pendiri Republik Turki.",
    "Based on Henry George's Progress and Poverty (1879).": "Berdasarkan Progress and Poverty karya Henry George (1879).",
    "Founded in 1884 in London; influenced the British Labour Party.": "Didirikan di London pada 1884; memengaruhi Partai Buruh Inggris.",
