    "The researched database was compiled from Wikipedia (spectrum and category articles), Britannica, and OpenStax/LibreTexts, then checked for distinctness: synonyms are listed as alternative names rather than separate entries. Classifications are approximations, not universal definitions.": "შესწავლილი ბაზა შედგენილია Wikipedia-ს (პოლიტიკური სპექტრისა და კატეგორიების სტატიები), Britannica-სა და OpenStax/LibreTexts-ის საფუძველზე და შემოწმებულია ცნებების გამიჯვნის მიზნით: სინონიმები მითითებულია ალტერნატიულ სახელებად და არა ცალკე ჩანაწერებად. კლასიფიკაციები მიახლოებითია და არა უნივერსალური განსაზღვრებები.",
