    "Migrated projects retain old category-based issue rules as a fallback when no family position is configured. Clearing all group positions removes both current and legacy rules.": "მიგრირებულ პროექტებში ძველი კატეგორიული ხმის მიცემის წესები შენარჩუნებულია სათადარიგოდ, თუ ოჯახისთვის პოზიცია მითითებული არ არის. ყველა ჯგუფური პოზიციის გასუფთავება წაშლის როგორც ახალ, ისე ძველ წესებს.",
