    "not": "არ",
    "merge them. Member parties keep their colours and are marked with the coalition-coloured ring. Parties may belong to several coalitions; the first coalition in the list determines the ring colour.": "აერთიანებს მათ. წევრი პარტიები ინარჩუნებენ საკუთარ ფერებს და აღინიშნება კოალიციის ფერის რგოლით. პარტია შეიძლება რამდენიმე კოალიციაში შედიოდეს; რგოლის ფერს სიაში პირველი კოალიცია განსაზღვრავს.",
