    "Christian democratic parties often sit between centre-right and centre; placement varies by country.": "ქრისტიან-დემოკრატიული პარტიები ხშირად მემარჯვენე ცენტრსა და ცენტრს შორის არიან; მათი პოზიცია ქვეყნიდან ქვეყანაში განსხვავდება.",
    "French tradition of national independence, a strong presidency, state-led economic planning and grandeur.": "საფრანგეთის პოლიტიკური ტრადიცია, რომელიც ეროვნულ დამოუკიდებლობას, ძლიერ პრეზიდენტობას, სახელმწიფოს მიერ ეკონომიკის დაგეგმვასა და ეროვნულ სიდიადეს უსვამს ხაზს.",
