    "Conservatism using government and faith-based groups to address poverty and social problems.": "კონსერვატიზმი, რომელიც სიღარიბისა და სოციალური პრობლემების მოსაგვარებლად სახელმწიფოსა და რელიგიურ ჯგუფებს იყენებს.",
