    "US synthesis of libertarian economics, traditional social values and anti-communism (Frank Meyer, National Review).": "ლიბერტარიანული ეკონომიკის, ტრადიციული სოციალური ღირებულებებისა და ანტიკომუნიზმის ამერიკული სინთეზი (ფრენკ მაიერი, National Review).",
    "Free market": "თავისუფალი ბაზარი",
    "Traditional values": "ტრადიციული ღირებულებები",
    "National identity based on shared citizenship, institutions and values rather than ethnicity.": "ეროვნული იდენტობა, რომელიც საერთო მოქალაქეობას, ინსტიტუტებსა და ღირებულებებს ეფუძნება და არა ეთნიკურობას.",
    "Inclusive-patriotic": "ინკლუზიური პატრიოტული",
    "Protects nature through conservative lenses: stewardship, property rights, market tools and tradition.": "ბუნებას იცავს კონსერვატიული ხედვით: მეურვეობა, საკუთრების უფლებები, საბაზრო ინსტრუმენტები და ტრადიცია.",
