    "Muslim-identity parties operating within democratic politics, analogous to Christian democracy.": "მუსლიმურ იდენტობაზე დაფუძნებული პარტიები, რომლებიც დემოკრატიული პოლიტიკის ფარგლებში მოქმედებენ და ქრისტიან-დემოკრატიას ჰგვანან.",
