    "Classification is debated; some analysts treat these parties as conservative-democrats, others as Islamist.": "კლასიფიკაცია სადავოა: ზოგი ანალიტიკოსი ამ პარტიებს კონსერვატიულ-დემოკრატიულად მიიჩნევს, სხვები კი ისლამისტურად.",
    "Range of moderate positions between left and right, favouring incremental reform and pragmatic compromise.": "მარცხენასა და მარჯვენას შორის ზომიერი პოზიციების სპექტრი, რომელიც ეტაპობრივ რეფორმებსა და პრაგმატულ კომპრომისს ემხრობა.",
    "Mixed economy": "შერეული ეკონომიკა",
    "Rejects the left–right dichotomy and ideology in favour of innovative, evidence-based reform from the centre.": "უარყოფს მარცხენა-მარჯვენა დაყოფასა და იდეოლოგიურ დოგმებს და ცენტრიდან ინოვაციურ, მტკიცებულებებზე დაფუძნებულ რეფორმებს ემხრობა.",
    "Market + targeted reform": "ბაზარი + მიზნობრივი რეფორმები",
    "Pragmatic, reformist": "პრაგმატული, რეფორმისტული",
