    "Market economy, variable regulation": "საბაზრო ეკონომიკა, რეგულირების განსხვავებული დონე",
    "Liberty, tolerance": "თავისუფლება, ტოლერანტობა",
    "Liberalism spans centre-right (classical) to centre-left (social liberalism); it is placed at the centre as the umbrella tradition.": "ლიბერალიზმი მოიცავს მემარჯვენე ცენტრიდან (კლასიკური ლიბერალიზმი) მემარცხენე ცენტრამდე (სოციალური ლიბერალიზმი) პოზიციებს; აქ იგი ფართო ტრადიციის სახით ცენტრშია მოთავსებული.",
    "Freedom as non-domination and civic virtue; stresses active citizenship, anti-corruption and mixed constitution.": "თავისუფლება, როგორც ბატონობის არარსებობა და სამოქალაქო სათნოება; ხაზს უსვამს აქტიურ მოქალაქეობას, ანტიკორუფციასა და შერეულ კონსტიტუციას.",
