    "Advocates international institutions, collective security, trade and human rights to keep peace.": "მხარს უჭერს საერთაშორისო ინსტიტუტებს, კოლექტიურ უსაფრთხოებას, ვაჭრობასა და ადამიანის უფლებებს მშვიდობის შესანარჩუნებლად.",
