    "Fiscal federalism": "ფისკალური ფედერალიზმი",
    "Pluralist": "პლურალისტური",
    "Policy judged by practical results rather than ideology; evidence-based governance.": "პოლიტიკა ფასდება პრაქტიკული შედეგებით და არა იდეოლოგიით; მტკიცებულებებზე დაფუძნებული მმართველობა.",
    "Whatever works": "რაც მუშაობს",
    "Government bound by constitutional limits, separation of powers and protected rights.": "კონსტიტუციური შეზღუდვებით, ხელისუფლების დანაწილებითა და დაცული უფლებებით შეკრული მთავრობა.",
    "Rights and procedure": "უფლებები და პროცედურა",
    "Seeks greater autonomy or recognition for a region without necessarily demanding independence.": "ცდილობს რეგიონისთვის მეტი ავტონომიის ან აღიარების მოპოვებას დამოუკიდებლობის აუცილებელი მოთხოვნის გარეშე.",
    "Regional development": "რეგიონული განვითარება",
    "Local identity": "ადგილობრივი იდენტობა",
    "Prefers decisions and services at the lowest practical level of government and community.": "გადაწყვეტილებების მიღებასა და მომსახურების გაწევას მმართველობისა და თემის პრაქტიკულად ყველაზე დაბალ დონეზე ამჯობინებს.",
    "Local economy": "ადგილობრივი ეკონომიკა",
    "Community-based": "თემზე დაფუძნებული",
    "Critiques political elites independent of left–right issues, often promising clean government and competence.": "აკრიტიკებს პოლიტიკურ ელიტებს მარცხენა-მარჯვენა საკითხებისგან დამოუკიდებლად და ხშირად სუფთა, კომპეტენტურ მმართველობას ჰპირდება.",
    "Mixed, pragmatic": "შერეული, პრაგმატული",
    "Anti-corruption": "ანტიკორუფციული",
    "Pursues social justice within a capitalist democracy through a welfare state, unions and regulation.": "კაპიტალისტური დემოკრატიის ფარგლებში სოციალური სამართლიანობის მიღწევას ცდილობს კეთილდღეობის სახელმწიფოს, პროფკავშირებისა და რეგულირების მეშვეობით.",
