    "Mass-line, authoritarian": "მასების ხაზი, ავტორიტარული",
    "Enver Hoxha's strictly Stalinist, anti-revisionist line rejecting Soviet reform and Maoism.": "ენვერ ხოჯას მკაცრად სტალინური, ანტირევიზიონისტული ხაზი, რომელიც უარყოფდა საბჭოთა რეფორმებსა და მაოიზმს.",
