    "Revolutionary Marxism stressing mass spontaneity, democracy within socialism and opposition to bureaucratic vanguardism.": "რევოლუციური მარქსიზმი, რომელიც ხაზს უსვამს მასების სპონტანურობას, სოციალიზმის შიდა დემოკრატიასა და ბიუროკრატიული ავანგარდიზმის წინააღმდეგობას.",
    "Socialised production": "გასაზოგადოებრიობებული წარმოება",
