    "Libertarian Marxist current in which workers' councils, not parties or states, run society.": "ლიბერტარიანული მარქსისტული მიმდინარეობა, რომლის მიხედვითაც საზოგადოებას მუშათა საბჭოები მართავენ და არა პარტიები ან სახელმწიფოები.",
