    "Communist left critical of Bolshevik party-state practice, parliamentarism and unions.": "კომუნისტური მემარცხენე მიმდინარეობა, რომელიც აკრიტიკებს ბოლშევიკურ პარტიულ-სახელმწიფოებრივ პრაქტიკას, პარლამენტარიზმსა და პროფკავშირებს.",
    "Abolition of wage labour": "დაქირავებული შრომის გაუქმება",
    "Internationalist, anti-parliamentary": "ინტერნაციონალისტური, ანტიპარლამენტური",
