    "Commons, anti-work tendencies": "საერთო რესურსები, შრომის საწინააღმდეგო ტენდენციები",
    "Movement-based, anti-authoritarian": "მოძრაობაზე დაფუძნებული, ანტიავტორიტარული",
    "Abolition of state, private property and capitalism in favour of voluntary communes and 'from each according to ability, to each according to need' (Kropotkin).": "სახელმწიფოს, კერძო საკუთრებისა და კაპიტალიზმის გაუქმება ნებაყოფლობითი კომუნების სასარგებლოდ და პრინციპით: „თითოეულისგან უნარის მიხედვით, თითოეულს საჭიროების მიხედვით“ (კროპოტკინი).",
    "Common ownership, free distribution": "საერთო საკუთრება, თავისუფალი განაწილება",
