    "Only deputies from parties marked Government are selectable. A deputy may hold more than one office.": "არჩევა შესაძლებელია მხოლოდ იმ პარტიების დეპუტატებისთვის, რომლებსაც მთავრობის სტატუსი აქვთ. ერთ დეპუტატს რამდენიმე თანამდებობის დაკავება შეუძლია.",
