    "This deputy is no longer eligible because their party is not currently designated Government. Clear or replace the appointment.": "ეს დეპუტატი დანიშვნისთვის შესაფერისი აღარ არის, რადგან მის პარტიას მთავრობის სტატუსი აღარ აქვს. გააუქმეთ ან შეცვალეთ დანიშვნა.",
