    "Party and ideological-family totals count deputies currently appointed from Government-designated parties. External appointees are counted separately.": "პარტიებისა და იდეოლოგიური ოჯახების სტატისტიკა ითვლის იმ დეპუტატებს, რომლებიც ამჟამად მთავრობის სტატუსის მქონე პარტიებიდან არიან დანიშნული. გარე კანდიდატები ცალკე ითვლებიან.",
