    "Sources & references": "Fuentes y referencias",
    "The researched database was compiled from Wikipedia (spectrum and category articles), Britannica, and OpenStax/LibreTexts, then checked for distinctness: synonyms are listed as alternative names rather than separate entries. Classifications are approximations, not universal definitions.": "La base documentada se elaboró a partir de Wikipedia (artículos sobre el espectro y las categorías), Britannica y OpenStax/LibreTexts, y se revisó para evitar duplicidades: los sinónimos figuran como nombres alternativos, no como entradas separadas. Las clasificaciones son aproximadas, no definiciones universales.",
