    "The original ideology descriptions and historical metadata are preserved. Positions are broad reference classifications; political movements have varied across time and place.": "Se conservan las descripciones originales de las ideologías y sus datos históricos. Las posiciones son clasificaciones generales orientativas; los movimientos políticos han variado según la época y el lugar.",
