    "Deputy appointment": "Nombramiento de diputado",
    "Only deputies from parties marked Government are selectable. A deputy may hold more than one office.": "Solo se pueden seleccionar diputados de partidos marcados como Gobierno. Un diputado puede ocupar más de un cargo.",
    "No deputy selected": "No se ha seleccionado ningún diputado",
    "This deputy is no longer eligible because their party is not currently designated Government. Clear or replace the appointment.": "Este diputado ya no es elegible porque su partido no está designado actualmente como parte del Gobierno. Elimina o sustituye el nombramiento.",
    "External / non-deputy appointee": "Nombramiento externo / no diputado",
    "Use this for presidents, monarch-appointed ministers, technocrats or other officeholders who are not sitting government deputies.": "Úsalo para presidentes, ministros nombrados por un monarca, técnicos u otros cargos que no sean diputados en ejercicio de partidos del Gobierno.",
    "Enter a person's name": "Introduce el nombre de una persona",
