    "+ Add custom position": "+ Añadir cargo personalizado",
    "Appointment statistics": "Estadísticas de nombramientos",
    "Party and ideological-family totals count deputies currently appointed from Government-designated parties. External appointees are counted separately.": "Los totales por partido y familia ideológica cuentan a los diputados nombrados actualmente desde partidos designados como parte del Gobierno. Los nombramientos externos se cuentan por separado.",
    "Appointments by party": "Nombramientos por partido",
    "Appointments by ideological family": "Nombramientos por familia ideológica",
    "No deputy appointments yet.": "Todavía no hay diputados nombrados.",
