    "Election options": "Opciones electorales",
    "Configure the scale of seat changes and any optional ideological preference.": "Configura la magnitud de los cambios de escaños y una preferencia ideológica opcional.",
    "Election volatility": "Intensidad del cambio",
    "Choose how strongly election results may shift party seat allocations.": "Elige cuánto pueden cambiar los resultados electorales la distribución de escaños de los partidos.",
    "1 — Gentle": "1 — Leve",
    "10 — Dramatic": "10 — Radical",
    "Electoral momentum": "Impulso electoral",
    "Optional preference for parties belonging to one ideological family.": "Preferencia opcional por los partidos pertenecientes a una familia ideológica.",
    "Momentum strength": "Fuerza del impulso",
    "Higher settings give the selected family a stronger advantage in the election.": "Los valores más altos conceden una mayor ventaja electoral a la familia seleccionada.",
    "1 — Subtle": "1 — Sutil",
    "10 — Landslide": "10 — Victoria aplastante",
    "Hold election": "Celebrar elecciones",
    "Election complete. Parliament's seat allocation has been updated.": "Las elecciones han terminado. Se ha actualizado la distribución de escaños del Parlamento.",
    "Allocate at least one seat to a party before holding an election.": "Asigna al menos un escaño a un partido antes de celebrar elecciones.",
