    "The researched database was compiled from Wikipedia (spectrum and category articles), Britannica, and OpenStax/LibreTexts, then checked for distinctness: synonyms are listed as alternative names rather than separate entries. Classifications are approximations, not universal definitions.": "調査済みデータベースは、Wikipedia（政治スペクトルおよびカテゴリーの記事）、Britannica、OpenStax/LibreTextsをもとに作成し、項目の重複がないか確認しています。同義語は別項目ではなく別名として記載しています。分類は近似的なもので、普遍的な定義ではありません。",
