    "Used in this parliament": "이 의회에서 사용 중",
    "assignment(s)": "건의 배정",
    "Economic characteristics": "경제적 특성",
    "Social characteristics": "사회적 특성",
    "Additional characteristics": "추가 특성",
    "Historical context": "역사적 맥락",
    "Related ideologies": "관련 이념",
    "Classification note:": "분류 참고:",
