    "Economic doctrine from Catholic social teaching (Chesterton, Belloc) favouring widespread ownership of productive property, neither capitalism nor socialism.": "가톨릭 사회교리(체스터턴, 벨록)에서 비롯된 경제 교리로, 자본주의나 사회주의가 아닌 생산 자산의 광범위한 소유를 지지한다.",
